SELECT DATE(create_time) AS date, SUM(promote_num) AS promote_num, SUM(intent_num) AS intent_num FROM promote_mgmt WHERE deleted = 0
AND YEAR(create_time) = #{year}
GROUP BY DATE(create_time) ORDER BY DATE(create_time) ASC

SELECT site AS site, SUM(promote_num) AS promoteNum, SUM(intent_num) AS intentNum FROM promote_mgmt WHERE deleted = 0
AND YEAR(create_time) = #{year}
GROUP BY site
